'use strict';
const BUILTIN_COACHES={
 kai:{name:'Kai',avatar:'🌿',tag:'Balanced & practical',tone:'Friendly',instructions:'Suggest affordable Filipino food. Encourage me without lecturing.',greeting:'Hi {{user_name}}, I’m Kai. Let’s make one practical choice for your food and movement today.'},
 aya:{name:'Aya',avatar:'🌸',tag:'Gentle & reassuring',tone:'Calm',instructions:'Be patient, reassuring and gentle. Offer one small step at a time. Avoid guilt or pressure.',greeting:'Hi {{user_name}}, Aya here. We can take today slowly. What would make looking after yourself a little easier?'},
 nico:{name:'Nico',avatar:'💪',tag:'Focused fitness buddy',tone:'Focused',instructions:'Be a practical fitness buddy. Offer manageable movement, rest and a clear next step. Celebrate consistency without body shaming.',greeting:'Hey {{user_name}}, Nico here. What time and energy do you have today? Let’s pick a manageable next step.'},
 mika:{name:'Mika',avatar:'✨',tag:'Playful & upbeat',tone:'Playful',instructions:'Be upbeat and lightly witty. Make healthy habits feel like approachable side quests. Keep nutrition information clear.',greeting:'Hey {{user_name}}, Mika here. Ready for a tiny wellness side quest? Food, movement, or a little motivation?'},
 chef:{name:'Chef Sol',avatar:'🥘',tag:'Food-first & budget wise',tone:'Friendly',instructions:'Focus on familiar Filipino meals, affordable swaps and flexible portions. Be warm and practical, and describe prices and nutrition as estimates.',greeting:'Kumusta, {{user_name}}! Chef Sol here. What’s in your kitchen, and what’s your food budget today?'},
 tala:{name:'Tala',avatar:'🌙',tag:'Calm routines & rest',tone:'Calm',instructions:'Help the user build calm daily routines around meals, rest and manageable movement. Use a grounded tone and do not diagnose sleep or health conditions.',greeting:'Hi {{user_name}}, I’m Tala. Let’s make a little room for food, rest and a routine that suits your day.'}
};
const LUNA_CHARACTER={fullName:'Bronwyn Delgado',age:'28',gender:'Woman',pronouns:'she/her',height:'174 cm',profession:'Owner of Raven’s Fuel, a chain of gas stations inherited from her father',relationship:'Single, unmarried',sexuality:'Bisexual',appearance:'A fair, porcelain-skinned adult woman with bright green eyes behind thin round black-framed glasses. She is nearsighted and sometimes squints with ironic curiosity. Long, thick black hair falls in waves below her waist. Full naturally dark-pink lips, a curvy feminine build with a defined waist and wide hips, and small moles across her shoulders and collarbones. Her movements are relaxed and her posture is quietly confident.',outfit:'Comfortable everyday clothes, black round glasses, and long black hair often tucked behind one ear.',background:'Her father left her Raven’s Fuel and a pragmatic attitude toward money: it is a tool for comfort, not a reason to change her everyday habits. She enjoys ordinary supermarket trips, joking with cashiers and returning to a cozy apartment in her Toyota Crown S220.',greeting:'Hey {{user_name}}, Luna here. Had a proper meal yet? Tell me what your day looks like—we’ll find something that fits, with a little less lecturing and a little more charm.'};
const LUNA_PROMPT='You are {{coach_name}}, a fictional adult wellness companion whose character biography is Bronwyn Delgado. Luna is your coach display name. Blend warmth, pragmatic common sense, calm confidence and playful, slightly roguish teasing. You are direct, patient and comfortable with yourself. Money is a tool for comfort; you value ordinary routines and familiar people. Enjoy witty hints, half-smiles and light, non-explicit flirting when the adult user welcomes it, while respecting their boundaries. Encourage eating, rest and manageable movement without guilt. Make affordable Filipino meal planning feel like an easy conversation. Support the user’s independence and real-world relationships. Stay transparent that you are an AI character. Let the user edit your appearance, biography and behavior.';
let userProfileDraft=null,profilePictureEpoch=0;
function normalizeUserProfile(p={}){return {avatarImage:validAvatar(p.avatarImage)?p.avatarImage:'',avatar:['👤','👩🏻','👨🏻','🧑🏻','🌻','🐱'].includes(p.avatar)?p.avatar:'👤',gender:['Woman','Man','Non-binary','Self-describe','Prefer not to say'].includes(p.gender)?p.gender:'Prefer not to say',customGender:String(p.customGender||'').slice(0,60),pronouns:String(p.pronouns||'').slice(0,40),bio:String(p.bio||'').slice(0,250)};}
function userAvatar(p=state.userProfile){const u=normalizeUserProfile(p);return u.avatarImage?`<img src="${u.avatarImage}" alt="Your profile picture">`:esc(u.avatar);}
function profileGender(p=state.userProfile){const u=normalizeUserProfile(p);return u.gender==='Self-describe'?u.customGender||'Self-described':u.gender;}
function replaceNames(text,c=state.coach){return String(text||'').replaceAll('{{user_name}}',state.name).replaceAll('{{coach_name}}',c.name||'Luna');}
function normalizeCharacter(p={}){const result={};for(const key of ['fullName','age','gender','pronouns','height','profession','relationship','sexuality','appearance','outfit','background','greeting'])result[key]=String(p[key]||'').slice(0,['appearance','background','greeting'].includes(key)?1500:250);return result;}
function makeBuiltinCoach(id='kai',saved={}){const template=BUILTIN_COACHES[id]||BUILTIN_COACHES.kai;const c=initial().coach;return {...c,...template,templateId:BUILTIN_COACHES[id]?id:'kai',tone:saved.tone||template.tone,language:saved.language||c.language,length:saved.length||c.length,vibe:saved.vibe===true,instructions:typeof saved.instructions==='string'?saved.instructions:template.instructions};}
function initializeBuiltinCoaches(){state.userProfile=normalizeUserProfile(state.userProfile);state.builtinProfiles=state.builtinProfiles||{};state.builtinChats=state.builtinChats||{};const migrated=state.coachProfiles.kaincheck,id=BUILTIN_COACHES[migrated.templateId]?migrated.templateId:'kai';if(!state.builtinProfiles[id]){state.builtinProfiles[id]=migrated;state.builtinChats[id]=state.coachChats.kaincheck||[];}for(const key of Object.keys(BUILTIN_COACHES)){state.builtinProfiles[key]=makeBuiltinCoach(key,state.builtinProfiles[key]||{});if(!Array.isArray(state.builtinChats[key]))state.builtinChats[key]=[];}state.activeBuiltinId=BUILTIN_COACHES[state.activeBuiltinId]?state.activeBuiltinId:id;state.coachProfiles.kaincheck=cloneCoach(state.builtinProfiles[state.activeBuiltinId]);state.coachChats.kaincheck=cloneCoach(state.builtinChats[state.activeBuiltinId]);}
function syncBuiltinCoach(){if(state.coachType!=='kaincheck')return;const id=state.coach.templateId||'kai';state.activeBuiltinId=id;state.builtinProfiles[id]=cloneCoach(state.coach);state.builtinChats[id]=cloneCoach(state.messages);}
function initializeCustomCharacters(){state.customProfiles=state.customProfiles||{};state.customChats=state.customChats||{};if(!Object.keys(state.customProfiles).length){const c=state.coachProfiles.custom,id=c.characterId||'character-1';state.customProfiles[id]={...c,characterId:id};state.customChats[id]=state.coachChats.custom||[];state.activeCustomId=id;}for(const [id,c] of Object.entries(state.customProfiles)){state.customProfiles[id]={...customCoach(c),characterId:id};if(!Array.isArray(state.customChats[id]))state.customChats[id]=[];}if(!state.customProfiles[state.activeCustomId])state.activeCustomId=Object.keys(state.customProfiles)[0];state.coachProfiles.custom=cloneCoach(state.customProfiles[state.activeCustomId]);state.coachChats.custom=cloneCoach(state.customChats[state.activeCustomId]);}
function syncCustomCharacter(){if(state.coachType!=='custom')return;const id=state.coach.characterId||state.activeCustomId||'character-1';state.activeCustomId=id;state.coach.characterId=id;state.coachProfiles.custom.characterId=id;state.customProfiles[id]=cloneCoach(state.coach);state.customChats[id]=cloneCoach(state.messages);}
function lunaDefaults(){return {name:'Luna',avatar:'🌙',templateId:'luna-bronwyn',lunaVersion:1,customConfigVersion:1,customPrompt:LUNA_PROMPT,character:cloneCoach(LUNA_CHARACTER),connection:{provider:'pkrd',url:'https://api.pawan.krd/v1/chat/completions',model:'pkrd/cosmosrp-2.1',temperature:.8,maxTokens:512,live:true}};}
function upgradeCustomCharacter(c){let result={...c};if(result.name==='Luna'&&result.lunaVersion!==1){const oldPrompt=String(result.customPrompt||'');const extra=oldPrompt&&!oldPrompt.startsWith('You are {{coach_name}}, a supportive wellness companion')?'\n\nAdditional saved instructions:\n'+oldPrompt:'';result={...result,...lunaDefaults(),customPrompt:(LUNA_PROMPT+extra).slice(0,6000),avatarImage:result.avatarImage||''};}result.character=normalizeCharacter(result.character);return result;}
function characterSettingsMarkup(c){const p=normalizeCharacter(c.character);const field=(key,label,placeholder='')=>`<label class="field"><span>${label}</span><input id="character-${key}" value="${esc(p[key])}" maxlength="250" placeholder="${placeholder}"></label>`;return `<details class="character-details"><summary>Character profile & appearance</summary><p class="subtle">Describe your fictional AI character. Your uploaded avatar changes its picture; these details guide its description and behavior.</p>${field('fullName','Full character name')}<div class="field-row">${field('age','Character age','Adult character age')}${field('height','Height','e.g. 174 cm')}${field('gender','Character gender')}${field('pronouns','Character pronouns','e.g. she/her')}</div>${field('profession','Profession or role')}<div class="field-row">${field('relationship','Relationship status')}${field('sexuality','Sexuality · optional')}</div><label class="field"><span>Appearance description</span><textarea id="character-appearance" rows="5" maxlength="1500" placeholder="Face, hair, eyes, build and distinctive features">${esc(p.appearance)}</textarea></label><label class="field"><span>Clothing & visual style</span><textarea id="character-outfit" rows="3" maxlength="250">${esc(p.outfit)}</textarea></label><label class="field"><span>Background & scenario</span><textarea id="character-background" rows="5" maxlength="1500">${esc(p.background)}</textarea></label><label class="field"><span>First message</span><textarea id="character-greeting" rows="4" maxlength="1500">${esc(p.greeting)}</textarea><small class="field-help">Use {{user_name}} and {{coach_name}} as placeholders.</small></label></details>`;}
function refreshCharacterDraft(){if(!settingsDraft||!$('#character-fullName'))return;const c={};for(const key of Object.keys(normalizeCharacter()))c[key]=$('#character-'+key)?.value||'';settingsDraft.character=normalizeCharacter(c);}
function characterPrompt(c){const p=normalizeCharacter(c.character);return Object.entries({Name:p.fullName,Age:p.age,Gender:p.gender,Pronouns:p.pronouns,Height:p.height,Profession:p.profession,Relationship:p.relationship,Sexuality:p.sexuality,Appearance:p.appearance,'Clothing and visual style':p.outfit,'Background and scenario':p.background}).filter(([,v])=>v).map(([k,v])=>k+': '+v).join('\n');}
function openUserProfile(){profilePictureEpoch++;userProfileDraft={...normalizeUserProfile(state.userProfile),name:state.name};userProfileModal();}
function userProfileModal(){const u=userProfileDraft;if(!u)return;activeModal='user-profile';showModal('Your profile',`<form id="user-profile-form"><div class="avatar-editor"><div class="uploaded-avatar" id="user-avatar-preview">${userAvatar(u)}</div><div><label class="upload-label" for="user-avatar-file">Choose profile picture</label><input id="user-avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden><p class="field-help">Saved on this device. PNG, JPEG or WebP, up to 5 MB.</p><button type="button" class="text-btn" data-action="remove-user-avatar" ${u.avatarImage?'':'hidden'}>Remove picture</button></div></div><label class="field"><span>Username</span><input id="user-display-name" value="${esc(u.name)}" maxlength="24" required></label><label class="field"><span>Gender</span><select id="user-gender">${['Woman','Man','Non-binary','Self-describe','Prefer not to say'].map(g=>`<option ${g===u.gender?'selected':''}>${g}</option>`).join('')}</select></label><label class="field" id="custom-gender-field" ${u.gender==='Self-describe'?'':'hidden'}><span>Describe your gender</span><input id="user-custom-gender" value="${esc(u.customGender)}" maxlength="60"></label><label class="field"><span>Pronouns · optional</span><input id="user-pronouns" value="${esc(u.pronouns)}" maxlength="40" placeholder="e.g. she/her, he/him, they/them"></label><label class="field"><span>About you · optional</span><textarea id="user-bio" maxlength="250" rows="3">${esc(u.bio)}</textarea></label><div class="save-bar"><button class="primary">Save profile</button></div></form>`);}
function refreshUserProfileDraft(){if(!userProfileDraft||!$('#user-profile-form'))return;Object.assign(userProfileDraft,{name:$('#user-display-name').value,gender:$('#user-gender').value,customGender:$('#user-custom-gender').value,pronouns:$('#user-pronouns').value,bio:$('#user-bio').value});}
async function uploadUserPicture(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Choose a PNG, JPEG or WebP image smaller than 5 MB.');return;}const epoch=profilePictureEpoch;try{const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>resolve(img);img.src=r.result;};r.readAsDataURL(file);});if(epoch!==profilePictureEpoch||activeModal!=='user-profile')return;const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const side=Math.min(image.width,image.height);canvas.getContext('2d').drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,256,256);refreshUserProfileDraft();userProfileDraft.avatarImage=canvas.toDataURL('image/jpeg',.86);$('#user-avatar-preview').innerHTML=userAvatar(userProfileDraft);$('[data-action="remove-user-avatar"]').hidden=false;}catch{toast('Could not open that image. Try another picture.');}}
function coachHub(){showModal('AI coach',`<p class="subtle">Choose who coaches you and make their style your own.</p><div class="coach-hub-current"><span class="coach-face">${coachAvatar()}</span><div><small>YOUR ACTIVE COACH</small><strong>${esc(state.coach.name)}</strong><p>${state.coachType==='custom'?'Your own AI · Custom / Proxy':'KainCheck AI · Built-in coach'}</p></div></div><button class="coach-hub-option" data-action="coach-library" aria-label="Choose a coach">${ic('user')}<span><strong>Choose a coach</strong><small>Browse KainCheck coaches or use your own AI.</small></span>${ic('arrow')}</button><button class="coach-hub-option" data-action="customize" aria-label="Customize coach">${ic('settings')}<span><strong>Customize coach</strong><small>${state.coachType==='custom'?'Edit personality, appearance and model settings.':'Edit tone, language, instructions and Vibe Mode.'}</small></span>${ic('arrow')}</button>`);}
function coachLibrary(){showModal('Find your kind of coach',`<button class="text-btn coach-hub-back" data-action="coach-hub">← AI coach</button><p class="subtle">Each KainCheck coach keeps its own preferences and chat. Your food log and daily plan are shared.</p><div class="coach-library">${Object.entries(BUILTIN_COACHES).map(([id,c])=>`<button class="coach-library-card ${state.coachType==='kaincheck'&&state.activeBuiltinId===id?'selected':''}" data-builtin-coach="${id}"><span>${c.avatar}</span><strong>${c.name}</strong><small>${c.tag}</small></button>`).join('')}</div><h3 class="library-heading">Custom AI character</h3><button class="luna-library-card" data-action="choose-luna"><span>🌙</span><div><strong>Luna · Bronwyn blend</strong><small>Warm, pragmatic, confident & playfully teasing<br>Editable appearance · Cosmos RP 2.1</small></div>${ic('arrow')}</button><div class="coach-library">${Object.entries(state.customProfiles).filter(([,c])=>!(c.name==='Luna'&&c.templateId==='luna-bronwyn')).map(([id,c])=>`<button class="coach-library-card" data-custom-character="${esc(id)}"><span>${coachAvatar(c)}</span><strong>${esc(c.name)}</strong><small>Your saved custom character</small></button>`).join('')}</div><button class="secondary" data-action="new-custom-character">${ic('plus')}Create a custom coach</button>`);}
function chooseBuiltinCoach(id){if(!BUILTIN_COACHES[id])return;save();resetEpoch++;activeChatController?.abort();chatBusy=false;state.activeBuiltinId=id;state.coachProfiles.kaincheck=cloneCoach(state.builtinProfiles[id]);state.coachChats.kaincheck=cloneCoach(state.builtinChats[id]);state.coachType='kaincheck';state.coach=cloneCoach(state.coachProfiles.kaincheck);state.messages=cloneCoach(state.coachChats.kaincheck);save();closeModal();screen='coach';render();toast(state.coach.name+' is your active KainCheck coach.');}
function chooseCustomCharacter(id){if(!state.platinum){subscription();return;}if(!state.customProfiles[id])return;save();resetEpoch++;activeChatController?.abort();chatBusy=false;state.activeCustomId=id;state.coachType='custom';state.coach=cloneCoach(state.customProfiles[id]);state.messages=cloneCoach(state.customChats[id]||[]);save();closeModal();screen='coach';render();customize();}
function chooseLuna(){if(!state.platinum){subscription();return;}save();let id=Object.keys(state.customProfiles).find(id=>state.customProfiles[id].name==='Luna'&&state.customProfiles[id].templateId==='luna-bronwyn');if(!id){id='luna-'+Date.now();state.customProfiles[id]=customCoach({...initial().coach,...lunaDefaults(),characterId:id});state.customChats[id]=[];}chooseCustomCharacter(id);}
function newCustomCharacter(){if(!state.platinum){subscription();return;}save();const id='character-'+Date.now();state.customProfiles[id]=customCoach({...initial().coach,name:'Your coach',avatar:'✨',characterId:id,customConfigVersion:1,customPrompt:'You are {{coach_name}}, a supportive fictional AI wellness companion for {{user_name}}. Add your personality, speaking style and boundaries here.',character:{},connection:lunaDefaults().connection});state.customChats[id]=[];chooseCustomCharacter(id);}
function updateSecureProviderUi(){const secure=$('#ai-provider')?.value==='pkrd';if(!$('#ai-base-url'))return;$('#ai-base-url').readOnly=false;$('#ai-model').readOnly=false;const keyField=$('#ai-key')?.closest('label');if(keyField)keyField.hidden=false;const notice=$('#secure-proxy-note');if(notice)notice.hidden=!secure;if($('#ai-max-tokens'))$('#ai-max-tokens').max=secure?'1024':'32768';if($('#ai-repetition-penalty'))$('#ai-repetition-penalty').min=secure?'1':'0';if($('#ai-top-k')){$('#ai-top-k').min=secure?'1':'0';$('#ai-top-k').max=secure?'100':'1000';}if(secure)populatePawanKey();}
function installPersonalization(){Object.assign(actions,{'coach-hub':coachHub,'edit-profile':openUserProfile,'coach-library':coachLibrary,'choose-luna':chooseLuna,'new-custom-character':newCustomCharacter,'remove-user-avatar':()=>{refreshUserProfileDraft();userProfileDraft.avatarImage='';$('#user-avatar-preview').innerHTML=userAvatar(userProfileDraft);$('[data-action="remove-user-avatar"]').hidden=true;}});
 document.addEventListener('click',e=>{const b=e.target.closest('button[data-builtin-coach]');if(b)chooseBuiltinCoach(b.dataset.builtinCoach);const custom=e.target.closest('button[data-custom-character]');if(custom)chooseCustomCharacter(custom.dataset.customCharacter);});
 document.addEventListener('input',e=>{if(e.target.closest('#user-profile-form'))refreshUserProfileDraft();});
 document.addEventListener('change',e=>{if(e.target.id==='user-avatar-file')uploadUserPicture(e.target.files?.[0]);if(e.target.closest('#user-profile-form')){refreshUserProfileDraft();$('#custom-gender-field').hidden=userProfileDraft.gender!=='Self-describe';if(!userProfileDraft.avatarImage)$('#user-avatar-preview').innerHTML=userAvatar(userProfileDraft);}if(e.target.id==='ai-provider')updateSecureProviderUi();});
 document.addEventListener('submit',e=>{if(e.target.id!=='user-profile-form')return;e.preventDefault();refreshUserProfileDraft();state.name=userProfileDraft.name.trim()||'Maria';state.userProfile=normalizeUserProfile(userProfileDraft);save();profilePictureEpoch++;closeModal();render(true);toast('Profile saved on this device.');});
}
